const q = ($input.first().json.query) || {};
let challenge = 'forbidden';
if (q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === $env.WHATSAPP_VERIFY_TOKEN) { challenge = q['hub.challenge']; }
return [{ json: { challenge } }];

// Extract sender, message text/button payload, phone_number_id (Spec 6.1).
const inp = $input.first().json;
const body = inp.body || inp;
let out = { isMessage: false };
try {
  const value = body.entry && body.entry[0] && body.entry[0].changes && body.entry[0].changes[0] && body.entry[0].changes[0].value;
  const msg = value && value.messages && value.messages[0];
  if (msg) {
    out = { isMessage: true,
      phone_number_id: value.metadata && value.metadata.phone_number_id,
      from: msg.from, msgId: msg.id,
      text: (msg.text && msg.text.body)
        || (msg.button && msg.button.text)
        || (msg.interactive && msg.interactive.button_reply && msg.interactive.button_reply.title)
        || '' };
  }
} catch (e) {}
return [{ json: out }];

// Find-or-create patient + conversation, write the inbound message, and
// return context + recent history in one round-trip (Spec 6.1). CTEs read the
// pre-insert snapshot, so prior_count / history exclude the current message,
// and wa_message_id de-dupes Meta webhook retries (inserted=0 => duplicate).
const p = $('Parse').first().json;
if (!p.isMessage) return [];
const esc = (s) => String(s == null ? '' : s).replace(/'/g, "''");
const pnid = esc(p.phone_number_id), from = esc(p.from), text = esc(p.text), msgId = esc(p.msgId);
const sql = `
with cl as (select id, name, timezone, google_calendar_id, staff_notify_number from clinics where phone_number_id = '${pnid}'),
pat as (insert into patients (clinic_id, whatsapp_number) select id, '${from}' from cl
  on conflict (clinic_id, whatsapp_number) do update set whatsapp_number = excluded.whatsapp_number returning id, clinic_id, is_returning),
con as (insert into conversations (clinic_id, patient_id, status, last_message_at) select pat.clinic_id, pat.id, 'bot', now() from pat
  on conflict (clinic_id, patient_id) do update set last_message_at = now() returning id, status),
prior as (select count(*)::int as prior_count from messages m join con on m.conversation_id = con.id),
ins as (insert into messages (clinic_id, conversation_id, role, content, wa_message_id) select pat.clinic_id, con.id, 'patient', '${text}', '${msgId}' from pat, con
  on conflict (wa_message_id) do nothing returning id),
recent as (select coalesce(json_agg(x order by x.created_at), '[]') as history from (
  select role, content, created_at from messages m join con on m.conversation_id = con.id order by created_at desc limit 10) x)
select cl.name as clinic_name, cl.timezone, cl.google_calendar_id, cl.staff_notify_number,
  pat.id as patient_id, pat.is_returning, con.id as conversation_id, con.status,
  prior.prior_count, (select count(*)::int from ins) as inserted, recent.history
from cl, pat, con, prior, recent;`;
return [{ json: { sql } }];

// Routing (Spec 6.1): duplicate -> stop; conversation in human mode -> notify
// staff and stay silent; emergency keyword -> flip to human + urgent notify +
// patient ack; otherwise -> bot path (RAG + LLM). Also decides bot disclosure
// (4.5) on the first message of a conversation.
const ctx = $('DB Context').first().json || {};
const p = $('Parse').first().json;
if (!ctx.clinic_name) return [];               // unknown phone_number_id: not our clinic
if (Number(ctx.inserted) === 0) return [];     // Meta retry of an already-processed message
const text = (p.text || '').toLowerCase();
const EMERGENCY = ['severe pain','bleeding','swelling','swollen','emergency','knocked out','knocked-out','broken jaw','can\u2019t breathe','cant breathe','can not breathe'];
const isEmergency = EMERGENCY.some((k) => text.includes(k));
let route = 'bot';
if (ctx.status === 'human') route = 'human';
else if (isEmergency) route = 'emergency';
const isFirst = Number(ctx.prior_count) === 0;
const disclosure = isFirst
  ? `Hi! You\u2019re chatting with ${ctx.clinic_name}\u2019s automated assistant \uD83E\uDD16 \u2014 I can help with questions, appointments, and reminders. A team member is always available if you need one.`
  : '';
return [{ json: { route, disclosure, is_first: isFirst, emergency: isEmergency,
  clinic_name: ctx.clinic_name, timezone: ctx.timezone, google_calendar_id: ctx.google_calendar_id,
  staff_notify_number: ctx.staff_notify_number, patient_id: ctx.patient_id, is_returning: ctx.is_returning,
  conversation_id: ctx.conversation_id, history: ctx.history || [],
  from: p.from, phone_number_id: p.phone_number_id, text: p.text } }];

// Emergency: flip conversation to human so the bot goes silent (4.4/4.6).
const t = $('Triage').first().json;
const sql = `update conversations set status='human', status_changed_at=now() where id='${t.conversation_id}';`;
return [{ json: Object.assign({}, t, { sql }) }];

// RAG retrieval scoped to this clinic (Spec 4.1 / 6.1). Uses the pgvector
// match_knowledge_base() function from db/schema.sql.
const t = $('Triage').first().json;
const emb = $('Embed Query').first().json;
const vec = emb && emb.data && emb.data[0] && emb.data[0].embedding;
if (!vec) return [{ json: Object.assign({}, t, { sql: null, no_embed: true }) }];
const lit = '[' + vec.join(',') + ']';
const sql = `select content, category, similarity from match_knowledge_base('${lit}'::vector, '${t.conversation_id ? t.patient_id : ''}'::uuid, 5);`;
// scope by clinic via patient's clinic: match_knowledge_base takes clinic_id.
const sql2 = `select kb.content, kb.category, 1 - (kb.embedding <=> '${lit}'::vector) as similarity
  from knowledge_base kb join patients p on p.clinic_id = kb.clinic_id
  where p.id = '${t.patient_id}' order by kb.embedding <=> '${lit}'::vector limit 5;`;
return [{ json: Object.assign({}, t, { sql: sql2 }) }];

const t = $('Triage').first().json;
const kbRows = $('KB Search').all().map((i) => i.json).filter((r) => r && r.content);
const tz = t.timezone || 'UTC';
const today = new Date().toLocaleDateString('en-CA', { timeZone: tz });
const clinic = t.clinic_name || 'the clinic';
const SYSTEM = `You are the receptionist assistant for ${clinic}, replying to patients on WhatsApp. You are not a general-purpose chatbot and not a medical professional.

## Grounding
- You have no clinic-specific facts unless they appear in a Knowledge base block below. Pricing, hours, services, staff, policies, insurance — state them only if present there. If absent or not covered, do not guess; say a team member will confirm.
- You may answer general health-education questions from your own knowledge, but mark them clearly as general information — never advice tailored to this patient, never a diagnosis.

## Tone
- Warm, professional, concise. If the patient mentions pain or discomfort, acknowledge briefly before logistics. Never argue with an upset patient — escalate instead.

## Actions
- To check availability, book, reschedule, cancel, or hand off to staff, call the provided tool. Don't claim an action is done until its result comes back. Only call book_appointment for a time the patient explicitly confirmed.

## After an action runs
- Availability: write ONE short intro sentence only (e.g. 'Here are the next available times:'). Tap buttons with the times are shown to the patient automatically — do NOT list times yourself.
- Booking: use exactly this format:
  ✅ Booked! [service] — [day date], [time][, with [provider] if known].
  We'll remind you the day before. Need to change it? Just message me.

## Conversation rule — always end with one next step
Every reply must close with exactly ONE offer, question, or call to action. Never a dead end.
- Price / hours / services → bridge to booking: 'Want me to check available times?'
- Any info answer → offer the most helpful next action
- Don't know → 'Want me to get a team member to answer this?'
Never end with more than one closing question.

## Keep it short
2–3 lines max per message. One idea per bubble.

## Language
Reply in the same language the patient uses. Urdu → Urdu. Roman Urdu → Roman Urdu. English → English.`;
const kbBlock = kbRows.length
  ? '

## Knowledge base (retrieved for this question)
' + kbRows.map((r) => `- [${r.category}] ${r.content}`).join('
')
  : '

## Knowledge base
(no relevant clinic facts retrieved for this message)';
const system = SYSTEM + kbBlock + `

## Patient context
Current date: ${today} (timezone ${tz}). is_returning: ${!!t.is_returning}.`;
const tools = [
  {type:'function',function:{name:'check_availability',description:'Find open appointment slots.',parameters:{type:'object',additionalProperties:false,properties:{date:{type:['string','null'],description:'YYYY-MM-DD or null'},time_preference:{type:'string',enum:['morning','afternoon','evening','any']},service_type:{type:['string','null']},provider_name:{type:['string','null']}},required:['date','time_preference','service_type','provider_name']}}},
  {type:'function',function:{name:'book_appointment',description:'Book a specific slot the patient explicitly confirmed. Only after check_availability.',parameters:{type:'object',additionalProperties:false,properties:{scheduled_at:{type:'string'},service_type:{type:'string'},provider_name:{type:['string','null']}},required:['scheduled_at','service_type','provider_name']}}},
  {type:'function',function:{name:'reschedule_appointment',description:'Move an existing appointment to a new confirmed time.',parameters:{type:'object',additionalProperties:false,properties:{appointment_id:{type:['string','null']},new_scheduled_at:{type:'string'}},required:['appointment_id','new_scheduled_at']}}},
  {type:'function',function:{name:'cancel_appointment',description:'Cancel an existing appointment.',parameters:{type:'object',additionalProperties:false,properties:{appointment_id:{type:['string','null']}},required:['appointment_id']}}},
  {type:'function',function:{name:'escalate_to_human',description:'Hand the conversation to clinic staff for emergencies, explicit requests for a person, or when you cannot help.',parameters:{type:'object',additionalProperties:false,properties:{reason:{type:'string'}},required:['reason']}}}
];
const history = Array.isArray(t.history) ? t.history : [];
const messages = [
  { role: 'system', content: system },
  ...history.map((m) => ({ role: m.role === 'patient' ? 'user' : 'assistant', content: m.content })),
  { role: 'user', content: t.text }
];
const body = { model: ($env.OPENAI_CHAT_MODEL || 'gpt-4o-mini'), max_tokens: 700, messages, tools, tool_choice: 'auto' };
return [{ json: { body } }];

const t = $('Triage').first().json;
const r = $input.first().json;
const choice = r.choices && r.choices[0];
const message = choice && choice.message;
const toolCall = message && message.tool_calls && message.tool_calls[0];
if (toolCall && choice.finish_reason === 'tool_calls') {
  let input = {};
  try { input = JSON.parse(toolCall.function.arguments || '{}'); } catch {}
  return [{ json: Object.assign({}, t, { mode: 'action', tool_name: toolCall.function.name, tool_id: toolCall.id, tool_input: input, assistant_message: message }) }];
}
let reply = (message && message.content) || 'Sorry, could you say that another way?';
if (t.disclosure) reply = t.disclosure + '\n\n' + reply;
return [{ json: Object.assign({}, t, { mode: 'reply', reply, role: 'bot' }) }];

const j = $input.first().json;
const esc = (s) => String(s == null ? '' : s).replace(/'/g, "''");
const logText = j.reply_body || j.reply;
const sql = `insert into messages (clinic_id, conversation_id, role, content) select clinic_id, '${j.conversation_id}', 'bot', '${esc(logText)}' from conversations where id='${j.conversation_id}';`;
return [{ json: Object.assign({}, j, { sql }) }];

