// Execute the LLM's chosen action. Produces action_result + plan.
const j = $input.first().json;
const name = j.tool_name, input = j.tool_input || {};
let plan = { kind: name };
let action_result = null;

if (name === 'escalate_to_human') {
  plan = { kind: 'escalate', reason: input.reason || 'patient requested a person' };

} else if (name === 'check_availability') {
  const tz = j.timezone || 'UTC';
  const date = input.date || new Date(Date.now() + 86400000).toLocaleDateString('en-CA', { timeZone: tz });
  const pref = input.time_preference || 'any';
  const windows = { morning: [9, 12], afternoon: [12, 17], evening: [17, 18], any: [9, 18] };
  const [startH, endH] = windows[pref] || windows.any;
  const slots = [];
  for (let h = startH; h < endH && slots.length < 3; h++) {
    const scheduledAt = date + 'T' + String(h).padStart(2, '0') + ':00:00';
    const d = new Date(scheduledAt);
    const label = (d.toLocaleDateString('en-US', { weekday:'short', month:'short', day:'numeric', timeZone: tz })
                 + ', ' + d.toLocaleTimeString('en-US', { hour:'numeric', minute:'2-digit', timeZone: tz })).substring(0, 20);
    slots.push({ scheduled_at: scheduledAt, label });
  }
  plan = { kind: 'check', date, startH, endH, service_type: input.service_type, provider_name: input.provider_name };
  action_result = { date, slots, note: 'Simulated availability' };

} else if (name === 'book_appointment') {
  plan = { kind: 'book', scheduled_at: input.scheduled_at, service_type: input.service_type || 'appointment', provider_name: input.provider_name || null };
  action_result = { booked: true, scheduled_at: input.scheduled_at, service_type: input.service_type, note: 'Calendar booking simulated' };

} else if (name === 'reschedule_appointment') {
  plan = { kind: 'reschedule', appointment_id: input.appointment_id, new_scheduled_at: input.new_scheduled_at };
  action_result = { rescheduled: true, new_scheduled_at: input.new_scheduled_at };

} else if (name === 'cancel_appointment') {
  plan = { kind: 'cancel', appointment_id: input.appointment_id };
  action_result = { cancelled: true };
}

return [{ json: Object.assign({}, j, { plan, action_result }) }];

const j = $input.first().json;
const result = j.action_result != null ? j.action_result : { note: 'action executed' };
const t = $('Triage').first().json;
const history = Array.isArray(t.history) ? t.history : [];
const assistantMsg = { role: 'assistant', content: null, tool_calls: [{ id: j.tool_id, type: 'function', function: { name: j.tool_name, arguments: JSON.stringify(j.tool_input || {}) } }] };
const toolResult = { role: 'tool', tool_call_id: j.tool_id, content: typeof result === 'string' ? result : JSON.stringify(result) };
const messages = [
  { role: 'system', content: 'You are the clinic receptionist assistant. Phrase the action result naturally and warmly for WhatsApp. For availability, offer the returned options and ask the patient to pick one. Keep it concise.' },
  ...history.map((m) => ({ role: m.role === 'patient' ? 'user' : 'assistant', content: m.content })),
  { role: 'user', content: t.text },
  assistantMsg,
  toolResult
];
const body = { model: ($env.OPENAI_CHAT_MODEL || 'gpt-4o-mini'), max_tokens: 500, messages };
return [{ json: Object.assign({}, j, { body }) }];

const r = $input.first().json;
const choice = r.choices && r.choices[0];
const message = choice && choice.message;
const prev = $('Execute Action').first().json;

// Availability result: build WhatsApp interactive button message
if (prev.plan && prev.plan.kind === 'check' && prev.action_result && prev.action_result.slots && prev.action_result.slots.length > 0) {
  const slots = prev.action_result.slots.slice(0, 3);
  const buttons = slots.map((s, i) => ({
    type: 'reply',
    reply: { id: 'slot_' + (i + 1), title: (s.label || s.scheduled_at).substring(0, 20) }
  }));
  const introText = (message && message.content) || 'Here are the next available times:';
  const cleanIntro = introText.split('\n')[0].substring(0, 1024);
  let reply = prev.disclosure ? prev.disclosure + '\n\n' + cleanIntro : cleanIntro;
  return [{ json: Object.assign({}, prev, { reply, reply_type: 'buttons', reply_body: cleanIntro, reply_buttons: buttons, mode: 'reply' }) }];
}

let reply = (message && message.content) || 'Done \u2014 let me know if you need anything else.';
if (prev.disclosure) reply = prev.disclosure + '\n\n' + reply;
return [{ json: Object.assign({}, prev, { reply, reply_type: 'text', mode: 'reply' }) }];
